import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target = inputs["target_positions"].copy()
    events = inputs["position_events"].copy()

    # Ensure correct dtypes / no stray index issues
    target = target.reset_index(drop=True)
    events = events.reset_index(drop=True)

    # 1. Dedup events by batch_seq (same event delivered more than once -> apply once)
    events = events.drop_duplicates(subset=["batch_seq"], keep="first")

    # Build target lookup: key -> (qty, price, row_version)
    target_map = {}
    for _, row in target.iterrows():
        key = (row["account_id"], row["symbol"])
        target_map[key] = {
            "qty": row["qty"],
            "price": row["price"],
            "row_version": row["row_version"],
        }

    # Group events by key
    events_by_key = {}
    for _, row in events.iterrows():
        key = (row["account_id"], row["symbol"])
        events_by_key.setdefault(key, []).append(row)

    # Final state container: key -> state dict or None (closed) ; also track whether
    # a key currently exists in target (for keys with no events at all -> carry forward)
    new_positions_rows = []
    closed_rows = []

    processed_keys = set()

    all_keys = set(target_map.keys()) | set(events_by_key.keys())

    for key in all_keys:
        account_id, symbol = key
        has_target = key in target_map
        state = dict(target_map[key]) if has_target else None

        key_events = events_by_key.get(key, [])

        if has_target:
            guard_version = target_map[key]["row_version"]
            filtered = [e for e in key_events if e["row_version"] > guard_version]
        else:
            filtered = list(key_events)

        # order by row_version, batch_seq
        filtered.sort(key=lambda e: (e["row_version"], e["batch_seq"]))

        closed_version = None
        touched = False

        for e in filtered:
            op = e["op"]
            qty_val = e["qty"]
            price_val = e["price"]
            row_version = e["row_version"]

            is_removal = (op == "D") or (op in ("I", "U") and (qty_val == 0))

            if is_removal:
                if state is not None:
                    state = None
                    closed_version = row_version
                    touched = True
                # else: no-op, no change to closed_version, not touched
            else:
                # I or U with qty != 0
                if state is not None:
                    new_qty = qty_val
                    if op == "U" and pd.isna(price_val):
                        new_price = state["price"]
                    else:
                        new_price = price_val
                    state = {
                        "qty": new_qty,
                        "price": new_price,
                        "row_version": row_version,
                    }
                else:
                    new_price = price_val  # NULL stays NULL
                    state = {
                        "qty": qty_val,
                        "price": new_price,
                        "row_version": row_version,
                    }
                closed_version = None
                touched = True

        if state is not None:
            new_positions_rows.append(
                {
                    "account_id": account_id,
                    "symbol": symbol,
                    "qty": state["qty"],
                    "price": state["price"],
                    "row_version": state["row_version"],
                }
            )
        else:
            if touched and closed_version is not None:
                closed_rows.append(
                    {
                        "account_id": account_id,
                        "symbol": symbol,
                        "closed_version": closed_version,
                    }
                )
            # else: nothing to emit (never existed, never created)

    new_positions = pd.DataFrame(
        new_positions_rows, columns=["account_id", "symbol", "qty", "price", "row_version"]
    )
    closed_positions = pd.DataFrame(
        closed_rows, columns=["account_id", "symbol", "closed_version"]
    )

    # Normalize dtypes
    if not new_positions.empty:
        new_positions["account_id"] = new_positions["account_id"].astype("int64")
        new_positions["qty"] = new_positions["qty"].astype("int64")
        new_positions["row_version"] = new_positions["row_version"].astype("int64")
        new_positions["price"] = new_positions["price"].astype("float64")
    else:
        new_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "qty": pd.Series(dtype="int64"),
                "price": pd.Series(dtype="float64"),
                "row_version": pd.Series(dtype="int64"),
            }
        )

    if not closed_positions.empty:
        closed_positions["account_id"] = closed_positions["account_id"].astype("int64")
        closed_positions["closed_version"] = closed_positions["closed_version"].astype("int64")
    else:
        closed_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "closed_version": pd.Series(dtype="int64"),
            }
        )

    return {
        "new_positions": new_positions,
        "closed_positions": closed_positions,
    }
